// check-orphan-lib.mjs — fail on build artifacts in lib/ whose source no
// longer exists (2026-10-24 PR #34: dead artifacts shipped because nobody
// deleted them). The expected emit set is derived deterministically from
// both tsconfigs (same options for every input), so no tsc run is needed.
//
// Not artifacts but legitimately present in lib/:
//   - lib/client.js — bundled by scripts/build-client.mjs from .client-build
//   - lib/lan-gate-server.cjs — the gateway server bundle entry
// Both are regenerated by the build, but they are NOT tsc outputs, so the
// src-mapping rule cannot account for them.
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')

const GENERATED_EXCEPTIONS = new Set(['client.js', 'lan-gate-server.cjs'])

function walk(dir, rel = '') {
  const out = []
  if (!existsSync(dir)) return out
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const abs = join(dir, entry.name)
    const relPath = rel ? `${rel}/${entry.name}` : entry.name
    if (entry.isDirectory()) out.push(...walk(abs, relPath))
    else if (entry.isFile()) out.push(relPath)
  }
  return out
}

// Full input closure: include expansion PLUS every transitively imported
// file (ts.createProgram resolves the import graph). An include-only list
// would flag every transitively-reached module's lib output as an orphan.
function tsconfigInputs(configPath) {
  const raw = execFileSync(process.execPath, [
    '-e',
    `const ts=require('typescript');const c=ts.readConfigFile(${JSON.stringify(configPath)},ts.sys.readFile);const p=ts.parseJsonConfigFileContent(c.config,ts.sys,${JSON.stringify(dirname(configPath))});const prog=ts.createProgram(p.fileNames,p.options);const names=prog.getSourceFiles().map(f=>f.fileName).filter(n=>!n.includes('node_modules'));console.log(JSON.stringify(names))`,
  ], { cwd: root, encoding: 'utf8' })
  return JSON.parse(raw).map((f) => relative(root, f).split('\\').join('/'))
}

// tsc emit mapping for one src file, derived from the tsconfig options
// (outDir lib, declarationDir lib/types, sourceMap+declarationMap on).
function expectedOutputs(srcFile) {
  if (!/\.tsx?$/.test(srcFile) || srcFile.endsWith('.d.ts')) return []
  const noExt = srcFile.replace(/\.tsx?$/, '')
  const rel = noExt.replace(/^src\//, '')
  return [
    `lib/${rel}.js`,
    `lib/${rel}.js.map`,
    `lib/types/${rel}.d.ts`,
    `lib/types/${rel}.d.ts.map`,
  ]
}

const expected = new Set()
for (const cfg of ['tsconfig.json', 'tsconfig.client.json']) {
  for (const srcFile of tsconfigInputs(cfg)) {
    if (!srcFile.startsWith('src/')) continue
    for (const out of expectedOutputs(srcFile)) expected.add(out)
  }
}

const orphans = []
for (const file of walk(join(root, 'lib'))) {
  const rel = `lib/${file}`
  if (expected.has(rel)) continue
  const stripped = rel.replace(/^lib\//, '')
  if (GENERATED_EXCEPTIONS.has(stripped)) continue
  orphans.push(rel)
}

if (orphans.length) {
  console.error('✗ lib/ 死产物门禁失败：发现孤儿构建产物（对应 src 源文件已不存在或不在 tsconfig 产出列表）')
  for (const f of orphans) {
    console.error(`  发现孤儿构建产物 ${f}，对应 src 源文件已不存在。请运行 git rm ${f} 并重新执行 pnpm build。`)
  }
  console.error('  说明：lib/client.js 与 lib/lan-gate-server.cjs 是打包产物（非 tsc 输出），已豁免；若确认它们也应重建，跑 pnpm build 即可。')
  process.exit(1)
}
console.log(`✓ lib/ 死产物门禁通过（${expected.size} 个预期产物全部对得上源码，无孤儿）`)
